pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory vals) public {
        vm.assume(tos.length == vals.length && tos.length > 0);
        vm.assume(tos.length <= 10);
        // bound values to avoid overflow in the safe version
        for (uint i = 0; i < vals.length; i++) {
            vals[i] = bound(vals[i], 0, 1e16);
        }
        uint256 balanceBefore = address(c.caddress()).balance;
        // execute with the original caller
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        try c.transfer(tos, vals) {
            // call succeeded, check balance not increased beyond total
        } catch {
            // ignore reverts
        }
        uint256 balanceAfter = address(c.caddress()).balance;
        // Compute total amount transferred (could overflow in buggy version)
        uint256 total = 0;
        for (uint i = 0; i < vals.length; i++) {
            total += vals[i] * 1e18;
        }
        assertTrue(balanceAfter <= balanceBefore + total);
    }
}

