pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound v[i] to avoid excessive assume rejections
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max);
        }

        // Ensure caller is the from address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        // Call transfer
        c.transfer(_tos, v);

        // For each element, check that if v[i] != 0, then the multiplication didn't overflow
        for (uint i = 0; i < v.length; i++) {
            if (v[i] != 0) {
                // The require in reference ensures: v[i]*1e18 / v[i] == 1e18
                // This is equivalent to no overflow (multiplication wraps around)
                assertTrue((v[i] * 1000000000000000000) / v[i] == 1000000000000000000, "Overflow occurred");
            }
        }
    }
}

