pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
    address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint256[] memory amounts) public {
        vm.assume(tos.length > 0 && tos.length == amounts.length);
        vm.assume(amounts.length <= 5);
        for (uint i = 0; i < amounts.length; i++) {
            amounts[i] = bound(amounts[i], 0, 10000);
        }

        // ensure msg.sender is the from address
        vm.prank(from);

        uint256 balanceBefore = address(target).balance;
        uint256 totalTransfer = 0;
        for (uint i = 0; i < amounts.length; i++) {
            if (amounts[i] != 0) {
                totalTransfer += amounts[i] * 1000000000000000000;
            }
        }

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, tos, amounts));
        // The reference always succeeds; we only care about cases where it would succeed
        vm.assume(success);

        uint256 balanceAfter = address(target).balance;
        assertTrue(balanceAfter - balanceBefore <= totalTransfer, "Balance increase exceeds allowed transfer");
    }
}
